PRAGMA foreign_keys = ON;

CREATE TABLE stations (id INTEGER PRIMARY KEY, name TEXT NOT NULL, address TEXT, phone TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE pumps (id INTEGER PRIMARY KEY, station_id INTEGER NOT NULL REFERENCES stations(id), name TEXT NOT NULL, system_type TEXT NOT NULL CHECK(system_type IN ('diesel','solar','equivalent_hybrid')), active INTEGER NOT NULL DEFAULT 1, notes TEXT);
CREATE TABLE beneficiaries (id INTEGER PRIMARY KEY, station_id INTEGER NOT NULL DEFAULT 1 REFERENCES stations(id), name TEXT NOT NULL, phone TEXT, address TEXT, location TEXT, jerba_number TEXT, area TEXT, status TEXT NOT NULL DEFAULT 'active', is_needy INTEGER NOT NULL DEFAULT 0, opening_balance INTEGER NOT NULL DEFAULT 0, carried_balance INTEGER NOT NULL DEFAULT 0, opening_diesel_liters REAL NOT NULL DEFAULT 0, carried_diesel_liters REAL NOT NULL DEFAULT 0, notes TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX idx_beneficiaries_name ON beneficiaries(name); CREATE INDEX idx_beneficiaries_phone ON beneficiaries(phone); CREATE INDEX idx_beneficiaries_jerba ON beneficiaries(jerba_number); CREATE INDEX idx_beneficiaries_location ON beneficiaries(location);
CREATE TABLE partners (id INTEGER PRIMARY KEY, station_id INTEGER NOT NULL DEFAULT 1 REFERENCES stations(id), name TEXT NOT NULL, phone TEXT, ownership_mode TEXT NOT NULL CHECK(ownership_mode IN ('shares','percentage')), shares_count INTEGER, ownership_percentage REAL, opening_balance INTEGER NOT NULL DEFAULT 0, carried_balance INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, notes TEXT);
CREATE TABLE workers (id INTEGER PRIMARY KEY, station_id INTEGER NOT NULL DEFAULT 1 REFERENCES stations(id), name TEXT NOT NULL, phone TEXT, job_title TEXT, pay_type TEXT NOT NULL CHECK(pay_type IN ('fixed','hourly','percentage')), fixed_salary INTEGER DEFAULT 0, hourly_rate INTEGER DEFAULT 0, percentage_rate REAL DEFAULT 0, opening_balance INTEGER NOT NULL DEFAULT 0, carried_balance INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, notes TEXT);
CREATE TABLE queue_entries (id INTEGER PRIMARY KEY, beneficiary_id INTEGER NOT NULL REFERENCES beneficiaries(id), position INTEGER NOT NULL, cycle_number INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL, last_served_at TEXT, postponed_count INTEGER NOT NULL DEFAULT 0, skip_reason TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE booking_requests (id INTEGER PRIMARY KEY, beneficiary_id INTEGER NOT NULL REFERENCES beneficiaries(id), created_at TEXT NOT NULL, status TEXT NOT NULL, scheduled_date TEXT, scheduled_start TEXT, scheduled_end TEXT, priority INTEGER, notes TEXT, cancel_reason TEXT, reviewed_by INTEGER, reviewed_at TEXT);
CREATE TABLE irrigation_sessions (id INTEGER PRIMARY KEY, beneficiary_id INTEGER NOT NULL REFERENCES beneficiaries(id), queue_entry_id INTEGER REFERENCES queue_entries(id), booking_id INTEGER REFERENCES booking_requests(id), pump_id INTEGER NOT NULL REFERENCES pumps(id), planned_start TEXT, actual_start TEXT, actual_end TEXT, status TEXT NOT NULL, timer_started_at TEXT, timer_stopped_at TEXT, diesel_before REAL DEFAULT 0, diesel_consumed REAL DEFAULT 0, diesel_after REAL DEFAULT 0, diesel_warning_shown INTEGER NOT NULL DEFAULT 0, postponement_reason TEXT, notes TEXT);
CREATE TABLE irrigations (id INTEGER PRIMARY KEY, station_id INTEGER NOT NULL REFERENCES stations(id), pump_id INTEGER NOT NULL REFERENCES pumps(id), beneficiary_id INTEGER REFERENCES beneficiaries(id), worker_id INTEGER REFERENCES workers(id), operator_worker_id INTEGER REFERENCES workers(id), partner_id INTEGER REFERENCES partners(id), party_type TEXT NOT NULL DEFAULT 'beneficiary' CHECK(party_type IN ('beneficiary','worker','partner')), booking_id INTEGER REFERENCES booking_requests(id), queue_entry_id INTEGER REFERENCES queue_entries(id), session_id INTEGER REFERENCES irrigation_sessions(id), date TEXT NOT NULL, start_datetime TEXT NOT NULL, end_datetime TEXT NOT NULL, minutes INTEGER NOT NULL, system_type TEXT NOT NULL, water_hourly_rate_snapshot INTEGER NOT NULL DEFAULT 0, diesel_liters_per_hour_snapshot REAL NOT NULL DEFAULT 0, diesel_price_snapshot INTEGER NOT NULL DEFAULT 0, solar_hourly_rate_snapshot INTEGER NOT NULL DEFAULT 0, third_type_hourly_rate_snapshot INTEGER NOT NULL DEFAULT 0, cloud_minutes INTEGER NOT NULL DEFAULT 0, chargeable_minutes INTEGER NOT NULL, water_amount INTEGER NOT NULL DEFAULT 0, diesel_amount INTEGER NOT NULL DEFAULT 0, total_amount INTEGER NOT NULL DEFAULT 0, paid_amount INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL, override_waiting_period INTEGER NOT NULL DEFAULT 0, override_reason TEXT, notes TEXT, created_by INTEGER, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE cloud_periods (id INTEGER PRIMARY KEY, irrigation_id INTEGER NOT NULL REFERENCES irrigations(id) ON DELETE CASCADE, start_datetime TEXT NOT NULL, end_datetime TEXT NOT NULL, minutes INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX idx_cloud_periods_irrigation ON cloud_periods(irrigation_id,start_datetime,end_datetime);
CREATE INDEX idx_irrigations_beneficiary_date ON irrigations(beneficiary_id,date); CREATE INDEX idx_irrigations_pump_time ON irrigations(pump_id,start_datetime,end_datetime);
CREATE TABLE diesel_movements (id INTEGER PRIMARY KEY, beneficiary_id INTEGER REFERENCES beneficiaries(id), irrigation_id INTEGER REFERENCES irrigations(id), cashbox_id INTEGER, kind TEXT NOT NULL CHECK(kind IN ('delivery','receipt','advance','consumption','correction','opening_balance')), liters REAL NOT NULL, unit_price INTEGER NOT NULL DEFAULT 0, amount INTEGER NOT NULL DEFAULT 0, date TEXT NOT NULL, notes TEXT, created_by INTEGER);
CREATE TABLE payment_methods (id INTEGER PRIMARY KEY, station_id INTEGER NOT NULL DEFAULT 1 REFERENCES stations(id), name TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('cash','check','bank_transfer','wallet','other')), account_number TEXT, bank_name TEXT, cashbox_id INTEGER, ledger_account_code TEXT, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE cashboxes (id INTEGER PRIMARY KEY, station_id INTEGER NOT NULL DEFAULT 1 REFERENCES stations(id), name TEXT NOT NULL, opening_balance INTEGER NOT NULL DEFAULT 0, current_balance INTEGER NOT NULL DEFAULT 0, currency TEXT NOT NULL DEFAULT 'YER', active INTEGER NOT NULL DEFAULT 1, ledger_account_code TEXT);
CREATE TABLE cashbox_transfers (id INTEGER PRIMARY KEY, from_cashbox_id INTEGER REFERENCES cashboxes(id), to_cashbox_id INTEGER REFERENCES cashboxes(id), amount INTEGER NOT NULL, date TEXT NOT NULL, is_opening_transfer INTEGER NOT NULL DEFAULT 0, reference TEXT, notes TEXT, created_by INTEGER);
CREATE TABLE payments (id INTEGER PRIMARY KEY, beneficiary_id INTEGER REFERENCES beneficiaries(id), partner_id INTEGER REFERENCES partners(id), worker_id INTEGER REFERENCES workers(id), amount INTEGER NOT NULL, date TEXT NOT NULL, payment_method_id INTEGER NOT NULL REFERENCES payment_methods(id), cashbox_id INTEGER NOT NULL REFERENCES cashboxes(id), reference_number TEXT, notes TEXT, status TEXT NOT NULL, created_by INTEGER, CHECK(((beneficiary_id IS NOT NULL)+(partner_id IS NOT NULL)+(worker_id IS NOT NULL))=1));
CREATE TABLE expenses (id INTEGER PRIMARY KEY, category TEXT NOT NULL CHECK(category IN ('workers','partners','fuel','oil','grease','maintenance','parts','transport','admin','other')), title TEXT NOT NULL, amount INTEGER NOT NULL, date TEXT NOT NULL, payment_method_id INTEGER REFERENCES payment_methods(id), cashbox_id INTEGER REFERENCES cashboxes(id), beneficiary_id INTEGER REFERENCES beneficiaries(id), worker_id INTEGER REFERENCES workers(id), partner_id INTEGER REFERENCES partners(id), attachment_path TEXT, notes TEXT, status TEXT NOT NULL, created_by INTEGER);
CREATE TABLE worker_transactions (id INTEGER PRIMARY KEY, worker_id INTEGER NOT NULL REFERENCES workers(id), date TEXT NOT NULL, type TEXT NOT NULL, hours REAL DEFAULT 0, rate_snapshot INTEGER DEFAULT 0, percentage_snapshot REAL DEFAULT 0, amount INTEGER NOT NULL, cashbox_id INTEGER REFERENCES cashboxes(id), reference_type TEXT, reference_id INTEGER, notes TEXT, created_by INTEGER);
CREATE TABLE partner_transactions (id INTEGER PRIMARY KEY, partner_id INTEGER NOT NULL REFERENCES partners(id), date TEXT NOT NULL, type TEXT NOT NULL, amount INTEGER NOT NULL, ownership_snapshot REAL, reference_type TEXT, reference_id INTEGER, notes TEXT, created_by INTEGER);
CREATE TABLE accounts (id INTEGER PRIMARY KEY, parent_id INTEGER REFERENCES accounts(id), code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, type TEXT NOT NULL);
CREATE TABLE journal_entries (id INTEGER PRIMARY KEY, date TEXT NOT NULL, reference_type TEXT, reference_id INTEGER, description TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'posted', created_by INTEGER, created_at TEXT NOT NULL);
CREATE TABLE journal_lines (id INTEGER PRIMARY KEY, journal_entry_id INTEGER NOT NULL REFERENCES journal_entries(id), account_id INTEGER NOT NULL REFERENCES accounts(id), beneficiary_id INTEGER REFERENCES beneficiaries(id), worker_id INTEGER REFERENCES workers(id), partner_id INTEGER REFERENCES partners(id), debit INTEGER NOT NULL DEFAULT 0, credit INTEGER NOT NULL DEFAULT 0, memo TEXT, CHECK(debit >= 0 AND credit >= 0 AND NOT(debit > 0 AND credit > 0)));
CREATE TABLE audit_logs (id INTEGER PRIMARY KEY, user_id INTEGER, operation TEXT NOT NULL, table_name TEXT NOT NULL, record_id INTEGER, old_values TEXT, new_values TEXT, reason TEXT, created_at TEXT NOT NULL);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE notifications (id INTEGER PRIMARY KEY, beneficiary_id INTEGER REFERENCES beneficiaries(id), type TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL, snoozed_until TEXT);
CREATE TABLE backup_records (id INTEGER PRIMARY KEY, path TEXT NOT NULL, created_at TEXT NOT NULL, status TEXT NOT NULL, notes TEXT);
CREATE TABLE sync_queue (id INTEGER PRIMARY KEY, operation TEXT NOT NULL, table_name TEXT NOT NULL, record_id INTEGER, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, last_error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
